const stateApp={filter:'all',showAll:false,view:'home'};
function setNavActive(key){$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.nav===key))}
function showHome(){stateApp.view='home';$('#editorView').hidden=true;$('#homeView').hidden=false;$('#crumbTitle').textContent='Overview';}
function renderCards(){const q=$('#searchInput').value.trim().toLowerCase();let arr=TOOLS.filter(t=>(stateApp.filter==='all'||t.cat===stateApp.filter)&&(!q||`${t.name} ${t.desc} ${t.keywords}`.toLowerCase().includes(q)));const count=arr.length;const limited=!q&&!stateApp.showAll&&stateApp.filter==='all';if(limited)arr=arr.slice(0,12);$('#toolsGrid').innerHTML=arr.map(t=>`<button class="tool-card" data-tool="${t.id}"><span class="card-top"><span class="tool-icon tone-${t.tone}">${icon(t.icon)}</span><span class="card-arrow">${icon('arrow')}</span></span><strong>${esc(t.name)}</strong><p>${esc(t.desc)}</p><span class="card-tag">${esc(t.tag)}</span></button>`).join('');$('#noTools').hidden=count>0;$('#allCount').textContent=TOOLS.length;const btn=$('#toggleAll');btn.hidden=Boolean(q)||stateApp.filter!=='all';btn.innerHTML=stateApp.showAll?`Show fewer tools ${icon('up')}`:`See all ${TOOLS.length} built-in tools ${icon('arrow')}`;$('#toggleAllTop').innerHTML=stateApp.filter==='all'&&stateApp.showAll?'Show fewer tools '+icon('up'):'View all tools '+icon('arrow');$$('.tab').forEach(b=>{const on=b.dataset.filter===stateApp.filter;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))})}
function changeFilter(filter){stateApp.filter=filter;stateApp.showAll=filter!=='all';renderCards()}


function closeSidebar(){$('#sidebar').classList.remove('open');$('#sideScrim').classList.remove('show')}
function nav(target){closeSidebar();if(target==='editor'){showEditor();return}showHome();if(target==='image'||target==='pdf'||target==='video'){setNavActive(target);changeFilter(target);setTimeout(()=>$('#toolsSection').scrollIntoView({behavior:'smooth',block:'start'}),20)}else{setNavActive('home');changeFilter('all');window.scrollTo({top:0,behavior:'smooth'})}}
$$('[data-nav]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();nav(b.dataset.nav)}));
$('#menuBtn').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#sideScrim').classList.add('show')});$('#sideScrim').addEventListener('click',closeSidebar);
$('#exploreBtn').addEventListener('click',()=>$('#toolsSection').scrollIntoView({behavior:'smooth',block:'start'}));
$$('.tab').forEach(b=>b.addEventListener('click',()=>{changeFilter(b.dataset.filter);setNavActive(['image','pdf','video'].includes(b.dataset.filter)?b.dataset.filter:'home')}));
function toggleAll(){stateApp.showAll=stateApp.filter==='all'?!stateApp.showAll:true;stateApp.filter='all';renderCards();if(!stateApp.showAll)$('#toolsSection').scrollIntoView({behavior:'smooth',block:'start'})}
$('#toggleAll').addEventListener('click',toggleAll);$('#toggleAllTop').addEventListener('click',toggleAll);
$('#toolsGrid').addEventListener('click',e=>{const btn=e.target.closest('[data-tool]');if(btn)openTool(btn.dataset.tool)});


$('#searchInput').addEventListener('input',()=>{if(stateApp.view!=='home')showHome();stateApp.filter='all';stateApp.showAll=true;renderCards();const q=$('#searchInput').value.trim();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#smallModal').hidden)closeSmall();else if(!$('#toolModal').hidden)closeTool();else closeSidebar()}if(e.key==='/'&&!/input|textarea|select/i.test(e.target.tagName)&&!e.target.isContentEditable){e.preventDefault();$('#searchInput').focus()}});
// PDF.js worker: loaded from this site on first PDF use, then cached.
const readyPdfEngine = (() => {
  let p = null;
  return () => p || (p = EngineStore.load('pdfWorkerCode')
    .then(code => {
      pdfjsLib.GlobalWorkerOptions.workerSrc = URL.createObjectURL(new Blob([code], {type:'application/javascript'}));
      return pdfjsLib;
    })
    .catch(() => { p = null; throw new Error('The local PDF engine could not load. Open this page over http(s), then retry.'); }));
})();
const pdfDocument = async opts => (await readyPdfEngine()).getDocument(opts);

