 const isImage=IMAGE_INPUT.has(id),isVideo=VIDEO_INPUT.has(id),isDocx=DOCX_INPUT.has(id),multi=MULTI_TOOLS.has(id),accept=isImage?'image/*':isVideo?'video/*':isDocx?'.docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document':'application/pdf,.pdf';
 const noun=isImage?(multi?'photos':'photo'):isVideo?'video':isDocx?'Word document':(multi?'PDFs':'PDF');
