 if(!s.files.length){html+=`<div class="drop-zone" id="dropZone" role="region" tabindex="0" aria-label="Choose ${noun}"><div class="drop-icon">${icon(isVideo?'video':'upload')}</div><strong>Drop your ${noun} here</strong><p>or choose from your device</p><div class="drop-actions"><button class="btn btn-primary" id="pickFile">${icon('plus')} Select ${noun}</button>${isImage?`<button class="btn btn-outline" id="takePhoto">${icon('camera')} Take a photo</button>`:''}</div><small>${isImage?'JPG, PNG, WebP and other browser-supported formats':isVideo?'Browser-supported video files':isDocx?'DOCX files · text only':'PDF files'} · Nothing is uploaded</small></div>`;}
