  const lockedPdf=id==='unlock-pdf';
  const preview=lockedPdf?`<div class="locked-preview">${icon('shield')}<strong>Encrypted PDF</strong><span>Enter its known password to unlock.</span></div>`:isDocx?`<div class="docx-preview">${esc((s.docxText||'').slice(0,1800))}${(s.docxText||'').length>1800?'\n…':''}</div>`:isVideo?`<video id="videoPreview" src="${esc(s.videoInfo?.url||'')}" controls playsinline preload="metadata"></video>`:`<canvas id="previewCanvas" width="100" height="100" ${id==='color-picker'?'style="cursor:crosshair"':''}></canvas>`;
