  const previewLabel=lockedPdf?'Preview unavailable until unlocked':isDocx?'First part of document':isVideo&&s.videoInfo?`${s.videoInfo.width} × ${s.videoInfo.height} · ${formatDuration(s.videoInfo.duration)}`:isImage?'Preview':'Rendering…';
  html+=`<div class="preview-block"><div class="preview-bar"><strong>${previewTitle}</strong><span id="previewLabel">${esc(previewLabel)}</span></div><div class="preview-surface ${isVideo?'video-surface':isImage?'':'pdf-surface'}">${preview}</div></div><div class="file-list">${s.files.map((f,i)=>`<div class="file-row"><span class="file-ic">${icon(isVideo?'video':isImage?'image':'file')}</span><span class="file-meta"><strong>${esc(f.name)}</strong><small>${fmtSize(f.size)}${!isImage&&!isVideo&&i===0&&s.pageCount?` · ${s.pageCount} page${s.pageCount===1?'':'s'}`:''}</small></span>${multi?`<button data-file-action="up" data-index="${i}" aria-label="Move file up" ${i===0?'disabled':''}>${icon('up')}</button><button data-file-action="down" data-index="${i}" aria-label="Move file down" ${i===s.files.length-1?'disabled':''}>${icon('down')}</button>`:''}<button data-file-action="remove" data-index="${i}" aria-label="Remove file">${icon('close')}</button></div>`).join('')}</div><div class="file-aux"><button class="add-files" id="addFiles">${multi?'+ Add more photos or files':'↻ Choose another file'}</button>${isImage?`<button class="add-files camera-again" id="takePhoto">${icon('camera')} Take a photo</button>`:''}</div><p class="preview-caption">${multi&&s.files.length>1?'Preview shows the first file; settings apply to all. ':''}Your file${s.files.length>1?'s are':' is'} processed in this browser.</p>`;
