 const camera=$('#toolCameraInput'),take=$('#takePhoto');if(camera&&take){camera.addEventListener('change',e=>handleFiles(e.target.files));take.addEventListener('click',e=>{e.stopPropagation();camera.click()})}
 const drop=$('#dropZone');if(drop){drop.addEventListener('click',e=>{if(!e.target.closest('button'))input.click()});drop.addEventListener('keydown',e=>{if(e.target===drop&&(e.key==='Enter'||e.key===' ')){e.preventDefault();input.click()}});['dragenter','dragover'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.add('dragging')}));['dragleave','drop'].forEach(x=>drop.addEventListener(x,e=>{e.preventDefault();drop.classList.remove('dragging')}));drop.addEventListener('drop',e=>handleFiles(e.dataTransfer.files))}
