function initSignaturePad(){const canvas=$('#signatureCanvas');if(!canvas||!toolState)return;const s=toolState,ctx=canvas.getContext('2d');ctx.lineCap='round';ctx.lineJoin='round';if(s.signatureData){const im=new Image();im.onload=()=>{if(toolState===s)ctx.drawImage(im,0,0,canvas.width,canvas.height)};im.src=s.signatureData}let drawing=false;function pos(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}}canvas.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;canvas.setPointerCapture(e.pointerId);const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.strokeStyle=val('sigColor','#25253c');ctx.lineWidth=Math.max(1,num('sigWidth',3))*2;ctx.lineTo(p.x+.01,p.y+.01);ctx.stroke();s.hasInk=true});canvas.addEventListener('pointermove',e=>{if(!drawing)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke()});function end(){if(drawing){drawing=false;s.signatureData=canvas.toDataURL('image/png')}}canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);$('#clearSignature').addEventListener('click',()=>{ctx.clearRect(0,0,canvas.width,canvas.height);s.hasInk=false;s.signatureData=''});}
async function loadImageFile(file,s){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);s.urls.push(url);const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error(`This browser could not decode “${file.name}”. Try JPG, PNG or WebP.`));image.src=url})}
function formatDuration(seconds){if(!Number.isFinite(seconds))return 'Unknown duration';const n=Math.max(0,Math.round(seconds)),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`}
async function loadVideoFile(file,s){const url=URL.createObjectURL(file);s.urls.push(url);return new Promise((resolve,reject)=>{const video=document.createElement('video');video.preload='auto';video.playsInline=true;video.muted=true;video.style.cssText='position:fixed;width:2px;height:2px;left:-10px;top:-10px;opacity:0;pointer-events:none';document.body.append(video);let settled=false;const timer=setTimeout(()=>fail('Video preview timed out; try a smaller or supported file.'),30000);function cleanListeners(){clearTimeout(timer);video.onloadeddata=null;video.onerror=null}function fail(message){if(settled)return;settled=true;cleanListeners();video.pause();video.removeAttribute('src');video.load();video.remove();reject(new Error(message))}video.onloadeddata=()=>{if(settled)return;const duration=video.duration,width=video.videoWidth,height=video.videoHeight;if(!width||!height||!Number.isFinite(duration)||duration<=0){fail('This video has no usable duration or video track.');return}settled=true;cleanListeners();resolve({url,duration,width,height,engine:video})};video.onerror=()=>fail('This browser cannot decode the selected video. Try a browser-supported MP4 or WebM.');video.src=url;video.load()})}
function releaseVideoResources(s){if(!s)return;try{s.videoCancel?.()}catch{}if(s.videoSource){try{s.videoSource.disconnect()}catch{}s.videoSource=null}if(s.videoAudioContext){try{s.videoAudioContext.close().catch(()=>{})}catch{}s.videoAudioContext=null}const video=s.videoInfo?.engine;if(video){try{video.pause();video.removeAttribute('src');video.load();video.remove()}catch{}}s.videoInfo=null}
function syncResizeFirst(s,reset=false){const img=s.images[0],preset=$('#choosePresets');if(preset)preset.disabled=!img;if(!img){s.resizePercent=null;return}if(reset){$('#resizeW').value=img.naturalWidth;$('#resizeH').value=img.naturalHeight;$('#resizeUnit').value='px';$('#keepRatio').checked=true;$('#writeDpi').checked=false;s.resizeUnit='px';s.resizePercent=null;s.resizeAnchor='width';setResizeLabel('Percent, print, social & file size');return}const unit=val('resizeUnit','px'),ratio=img.naturalWidth/img.naturalHeight;if(s.resizePercent!==null){const dpi=Math.max(1,num('resizeDpi',300));$('#resizeW').value=roundSize(fromPixels(img.naturalWidth*s.resizePercent/100,unit,dpi),unit);$('#resizeH').value=roundSize(fromPixels(img.naturalHeight*s.resizePercent/100,unit,dpi),unit)}else if($('#keepRatio')?.checked){if(s.resizeAnchor==='height')$('#resizeW').value=roundSize(num('resizeH',1)*ratio,unit);else $('#resizeH').value=roundSize(num('resizeW',1)/ratio,unit)}}
async function handleFiles(fileList){
 const s=toolState;if(!s||!fileList?.length)return;if(s.busy){toast('Wait for processing to finish or cancel it before changing files.',true);return}
 const isImage=IMAGE_INPUT.has(s.id),isVideo=VIDEO_INPUT.has(s.id),isDocx=DOCX_INPUT.has(s.id),multi=MULTI_TOOLS.has(s.id),wasEmpty=!s.files.length;let files=Array.from(fileList);if(!multi)files=files.slice(0,1);
 try{
  if(s.id==='slideshow'&&s.files.length+files.length>20)throw new Error('Choose at most 20 photos for a slideshow.');
  for(const f of files){
   if(isImage&&!(f.type.startsWith('image/')||/\.(png|jpe?g|webp|gif|bmp|avif|heic)$/i.test(f.name)))throw new Error('Please choose an image file.');
   if(isVideo&&!(f.type.startsWith('video/')||/\.(mp4|webm|mov|m4v|ogv)$/i.test(f.name)))throw new Error('Please choose a video file.');
   if(isDocx&&!/\.docx$/i.test(f.name))throw new Error('Please choose a DOCX file. Older DOC files are not supported.');
   if(!isImage&&!isVideo&&!isDocx&&!(f.type==='application/pdf'||/\.pdf$/i.test(f.name)))throw new Error('Please choose a PDF file.');
  }
  let images=[];if(isImage)images=await Promise.all(files.map(f=>loadImageFile(f,s)));
  let videoInfo=null;if(isVideo)videoInfo=await loadVideoFile(files[0],s);
  let docxText=null;if(isDocx)docxText=await readDocxText(files[0]);
  let firstPdf=null;if(!isImage&&!isVideo&&!isDocx&&s.id!=='unlock-pdf'&&(wasEmpty||!multi)){try{firstPdf=await PDFLib.PDFDocument.load(await files[0].arrayBuffer(),{updateMetadata:false})}catch(err){if(/encrypt/i.test(err.message||''))throw new Error('This PDF is encrypted. Unlock it first using a suitable PDF tool.');throw new Error('Could not read this PDF. Check that the file is valid and not encrypted.')}}
  if(toolState!==s){if(videoInfo?.engine){videoInfo.engine.pause();videoInfo.engine.removeAttribute('src');videoInfo.engine.load();videoInfo.engine.remove()}return}
  if(isVideo)releaseVideoResources(s);
  if(multi){s.files.push(...files);s.images.push(...images)}else{s.files=files;s.images=images;s.pageCount=0;s.formFields=[];s.ocrText=null}
  if(isDocx)s.docxText=docxText;
  if(firstPdf){s.pageCount=firstPdf.getPageCount();if(s.id==='form-pdf')s.formFields=discoverFields(firstPdf)}
  if(isVideo){s.videoInfo=videoInfo;const budget=Math.max(100000,files[0].size*8/videoInfo.duration*.7-96000);const choices=[2500000,1500000,800000,400000];$('#videoBitrate').value=String(choices.find(x=>x<=budget)||400000)}
  if(s.id==='form-pdf')renderOptions();
  if(RESIZE_TOOLS.has(s.id))syncResizeFirst(s,wasEmpty);
  renderWork();
 }catch(err){toast(err.message||'Could not open that file.',true);console.error(err)}
}
async function fileAction(action,index){
 const s=toolState;if(!s)return;if(s.busy){toast('Wait for processing to finish or cancel it before changing files.',true);return}
 const isImage=IMAGE_INPUT.has(s.id),isVideo=VIDEO_INPUT.has(s.id),isDocx=DOCX_INPUT.has(s.id),oldFirst=s.files[0];
 if(action==='remove'){s.files.splice(index,1);if(isImage)s.images.splice(index,1)}else{const next=index+(action==='up'?-1:1);if(next<0||next>=s.files.length)return;[s.files[index],s.files[next]]=[s.files[next],s.files[index]];if(isImage)[s.images[index],s.images[next]]=[s.images[next],s.images[index]]}
 if(!isImage&&!isVideo&&!isDocx){s.pageCount=0;if(s.files.length&&s.id!=='unlock-pdf'){try{s.pageCount=(await loadPdf(s.files[0])).getPageCount()}catch(e){console.warn(e)}}}if(!s.files.length)s.ocrText=null;
 if(toolState!==s)return;if(isVideo&&!s.files.length)releaseVideoResources(s);if(RESIZE_TOOLS.has(s.id)&&s.files[0]!==oldFirst)syncResizeFirst(s,false);
 if(s.id==='form-pdf'&&!s.files.length){s.formFields=[];renderOptions()}renderWork();
}
function discoverFields(doc){try{return doc.getForm().getFields().flatMap(f=>{const name=f.getName();if(f instanceof PDFLib.PDFTextField)return[{name,type:'text',value:f.getText()||'',maxLength:f.getMaxLength?.()}];if(f instanceof PDFLib.PDFCheckBox)return[{name,type:'check',value:f.isChecked()}];if(f instanceof PDFLib.PDFDropdown)return[{name,type:'dropdown',options:f.getOptions(),value:f.getSelected()?.[0]||''}];if(f instanceof PDFLib.PDFRadioGroup)return[{name,type:'radio',options:f.getOptions(),value:f.getSelected()||''}];return[]})}catch(e){console.warn('Form field discovery',e);return[]}}
$('#optionsArea').addEventListener('input',e=>{
 const s=toolState;if(!s)return;const target=e.target;
 if(target.type==='range'){const out=$('#'+target.id+'Out');if(out)out.textContent=target.value+(target.dataset.suffix||'')}
 if(RESIZE_TOOLS.has(s.id)&&['resizeW','resizeH'].includes(target.id)){
  s.resizePercent=null;s.resizeAnchor=target.id==='resizeW'?'width':'height';const label=$('#resizePresetLabel');if(label)label.textContent='Custom dimensions';
  if($('#keepRatio')?.checked&&s.images[0]){const ratio=s.images[0].naturalWidth/s.images[0].naturalHeight;if(target.id==='resizeW')$('#resizeH').value=roundSize(Number(target.value)/ratio,$('#resizeUnit').value);else $('#resizeW').value=roundSize(Number(target.value)*ratio,$('#resizeUnit').value)}
 }
 if(RESIZE_TOOLS.has(s.id)&&target.id==='resizeDpi'&&val('resizeUnit')!=='px')s.resizePercent=null;
 if(s.id==='compress-video')updateVideoEstimate();schedulePreview();
});
$('#optionsArea').addEventListener('change',e=>{
 const s=toolState;if(!s)return;const id=e.target.id;
 if(RESIZE_TOOLS.has(s.id)){
  if(id==='resizeUnit'){const old=s.resizeUnit,newUnit=e.target.value,dpi=Math.max(1,num('resizeDpi',300));const w=toPixels(num('resizeW',1),old,dpi),h=toPixels(num('resizeH',1),old,dpi);$('#resizeW').value=roundSize(fromPixels(w,newUnit,dpi),newUnit);$('#resizeH').value=roundSize(fromPixels(h,newUnit,dpi),newUnit);s.resizeUnit=newUnit;if(newUnit!=='px')enablePrintDpi()}
  if(id==='keepRatio'){s.resizePercent=null;if(e.target.checked)syncResizeFirst(s,false)}
  if(id==='limitTarget'){$('#resizeTargetGroup').hidden=!e.target.checked;if(e.target.checked&&val('outFormat')==='image/png'){$('#outFormat').value='image/jpeg';toast('JPG selected for the file-size limit.')}}
  if(id==='outFormat'&&$('#limitTarget')?.checked&&e.target.value==='image/png'){e.target.value='image/jpeg';toast('Choose JPG or WebP when limiting file size.',true)}
  if(id==='writeDpi'&&e.target.checked&&val('outFormat')==='image/webp'){$('#outFormat').value='image/jpeg';toast('JPG selected for print DPI metadata.')}
  if(id==='outFormat'&&e.target.value==='image/webp'&&$('#writeDpi')?.checked){$('#writeDpi').checked=false;toast('DPI metadata is not written to WebP.')}
 }
 if(s.id==='compress-video')updateVideoEstimate();schedulePreview();
});
const roundSize=(n,unit)=>unit==='px'?Math.round(n):Math.round(n*1000)/1000;
const toPixels=(n,unit,dpi)=>unit==='px'?n:unit==='cm'?n/2.54*dpi:unit==='mm'?n/25.4*dpi:n*dpi;
const fromPixels=(n,unit,dpi)=>unit==='px'?n:unit==='cm'?n*2.54/dpi:unit==='mm'?n*25.4/dpi:n/dpi;
function schedulePreview(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>refreshPreview(),130)}
async function refreshPreview(){const s=toolState;if(!s||!s.files.length||!$('#previewCanvas'))return;const seq=++s.seq;try{if(IMAGE_INPUT.has(s.id)){const c=await makeImageCanvas(s,true);if(toolState!==s||seq!==s.seq)return;const target=$('#previewCanvas');target.width=c.width;target.height=c.height;target.getContext('2d').drawImage(c,0,0);$('#previewLabel').textContent=`${c.dataset.outputWidth||c.width} × ${c.dataset.outputHeight||c.height} px`;if(s.id==='color-picker'){target.onclick=e=>{const r=target.getBoundingClientRect();const x=Math.min(target.width-1,Math.max(0,Math.floor((e.clientX-r.left)*target.width/r.width))),y=Math.min(target.height-1,Math.max(0,Math.floor((e.clientY-r.top)*target.height/r.height)));const d=target.getContext('2d').getImageData(x,y,1,1).data;const hex='#'+Array.from(d.slice(0,3)).map(v=>v.toString(16).padStart(2,'0')).join('').toUpperCase();$('#colorHex').textContent=hex;$('#colorSwatch').style.background=hex}}}else{const data=new Uint8Array(await s.files[0].arrayBuffer());const pdf=await pdfDocument({data,useSystemFonts:true}).promise;const page=await pdf.getPage(1);const view=page.getViewport({scale:Math.min(1.5,700/page.getViewport({scale:1}).width)});const c=document.createElement('canvas');c.width=Math.ceil(view.width);c.height=Math.ceil(view.height);await page.render({canvasContext:c.getContext('2d'),viewport:view}).promise;if(toolState!==s||seq!==s.seq)return;const target=$('#previewCanvas');target.width=c.width;target.height=c.height;target.getContext('2d').drawImage(c,0,0);$('#previewLabel').textContent=`${pdf.numPages} page${pdf.numPages===1?'':'s'}`;await pdf.destroy()}}catch(err){if(toolState===s&&seq===s.seq){const label=$('#previewLabel');if(label)label.textContent='Preview unavailable';console.warn('Preview:',err)}}}

/* Resize presets: each preset maps to actual local image processing. */
const RESIZE_PRESETS={
 easyResize:[{label:'Small',scale:.5,quality:.4},{label:'Medium',scale:.75,quality:.7},{label:'Large',scale:1,quality:.9}],
 percentages:[25,40,50,75],widths:[600,768,1024,1200],
 fileSizes:[{label:'100 KB',bytes:100*1024},{label:'500 KB',bytes:500*1024},{label:'1 MB',bytes:1024*1024},{label:'2 MB',bytes:2*1024*1024}]
};
