 ['Instagram',[['Square post',1080,1080],['Portrait post',1080,1350],['Story / Reel',1080,1920],['Landscape',1080,566],['Profile picture',320,320]]],
 ['Facebook',[['Profile picture',170,170],['Page cover',820,312],['Shared post',1200,630],['Page cover · high resolution',1640,624],['Profile picture · high resolution',320,320],['Story',1080,1920]]],
 ['YouTube',[['Thumbnail',1280,720],['Channel banner',2560,1440],['Channel icon',800,800],['Shorts',1080,1920]]],
 ['X (Twitter)',[['Post',1600,900],['Header',1500,500],['Profile picture',400,400]]],
 ['TikTok',[['Video / cover',1080,1920],['Profile picture',200,200]]],
 ['LinkedIn Personal',[['Profile picture',400,400],['Profile cover',1584,396],['Shared post',1200,627]]],
 ['LinkedIn Company',[['Company logo',300,300],['Company cover',1128,191],['Shared post',1200,627]]],
 ['Pinterest',[['Portrait pin',1000,1500],['Square pin',1000,1000],['Profile picture',165,165]]],
 ['Snap',[['Story',1080,1920]]],
 ['Tumblr',[['Dashboard image',1280,1920],['Profile picture',128,128]]]
