const MARKET_PRESETS=[['Etsy',[['Listing photo',2000,2000],['Shop icon',500,500],['Shop banner',3360,840]]],['Vinted',[['Portrait photo',1200,1600],['Square photo',1200,1200]]]];
function presetChoice(label,detail,attrs){return `<button class="preset-choice" ${attrs}><span>${esc(label)}</span><small>${esc(detail)}</small>${icon('chevron')}</button>`}
function sizeChoice(w,iw,ih){return presetChoice(`${w} × ${Math.max(1,Math.round(w*ih/iw))} px`,'Keep original proportions',`data-preset="width" data-value="${w}"`)}
function presetGroups(groups){return groups.map(([name,items])=>`<details class="preset-details"><summary>${esc(name)} ${icon('down')}</summary><div class="preset-details-body">${items.map(([label,w,h])=>presetChoice(label,`${w} × ${h} px`,`data-preset="exact" data-w="${w}" data-h="${h}" data-label="${esc(name+' · '+label)}"`)).join('')}</div></details>`).join('')}
function openResizePresets(){
 const s=toolState,img=s?.images?.[0];if(!s||!RESIZE_TOOLS.has(s.id)||!img){toast('Choose a photo first.',true);return}
 const iw=img.naturalWidth,ih=img.naturalHeight,ratio=`${iw} × ${ih} px`;
 const pct=p=>presetChoice(`${p}%`,`${Math.max(1,Math.round(iw*p/100))} × ${Math.max(1,Math.round(ih*p/100))} px`,`data-preset="percent" data-value="${p}"`);
 const target=(k,label)=>presetChoice(label,'Target maximum per photo',`data-preset="target" data-value="${k}"`);
 const print=[['Passport · 3.5 × 4.5 cm',3.5,4.5,'cm'],['Signature · 6 × 2 cm',6,2,'cm'],['A4 · 210 × 297 mm',210,297,'mm'],['A5 · 148 × 210 mm',148,210,'mm'],['Photo · 4 × 6 in',4,6,'in'],['Photo · 5 × 7 in',5,7,'in']].map(([label,w,h,unit])=>presetChoice(label,'300 DPI · exact frame',`data-preset="print" data-w="${w}" data-h="${h}" data-unit="${unit}" data-label="${esc(label)}"`)).join('');
 const html=`<div class="preset-dialog"><p class="preset-intro">Original photo: <b>${esc(ratio)}</b>. For multiple photos, percentage and width presets keep each photo’s proportions.</p>
 <details class="preset-section preset-category" open><summary class="preset-section-head"><h3>Easy resize</h3><span>ROUGH ESTIMATES</span>${icon('down')}</summary><div class="preset-category-body"><div class="easy-grid">${RESIZE_PRESETS.easyResize.map(({label,scale,quality})=>`<button class="easy-preset" data-preset="easy" data-label="${label}" data-value="${scale*100}" data-quality="${quality*100}"><b>${label}</b><span>${scale*100}% scale</span><span>${quality*100}% quality</span><span><i id="easyEstimate${label}">estimating…</i></span></button>`).join('')}</div><div class="help-text">Estimates for the first photo use each preset's quality before any file-size limit. A limit may lower quality or dimensions. JPG/WebP use quality; PNG does not. Actual size may differ.</div></div></details>
 <details class="preset-section preset-category"><summary class="preset-section-head"><h3>Percentage</h3><span>PROPORTIONAL</span>${icon('down')}</summary><div class="preset-category-body"><div class="preset-list">${RESIZE_PRESETS.percentages.map(pct).join('')}<details class="preset-details"><summary>More percentages ${icon('down')}</summary><div class="preset-details-body">${[10,20,30,60,80,90,100,125,150,200].map(pct).join('')}</div></details></div><div class="preset-custom"><input id="customPercent" type="number" min="1" max="400" step="any" value="100" aria-label="Custom percentage"><span>%</span><button class="btn btn-outline" id="applyPercent">Use custom %</button></div><div id="customPercentDimensions" class="help-text" aria-live="polite">100% → ${iw} × ${ih} px</div></div></details>
 <details class="preset-section preset-category"><summary class="preset-section-head"><h3>Width × height</h3><span>PIXELS</span>${icon('down')}</summary><div class="preset-category-body"><div class="preset-list">${RESIZE_PRESETS.widths.map(w=>sizeChoice(w,iw,ih)).join('')}<details class="preset-details"><summary>More widths ${icon('down')}</summary><div class="preset-details-body">${[320,480,720,1280,1600,1920,2560].map(w=>sizeChoice(w,iw,ih)).join('')}</div></details></div><button class="preset-inline" data-preset="custom-dimensions">Custom width & height ${icon('arrow')}</button></div></details>
 <details class="preset-section preset-category"><summary class="preset-section-head"><h3>File size</h3><span>PER PHOTO</span>${icon('down')}</summary><div class="preset-category-body"><div class="preset-list">${RESIZE_PRESETS.fileSizes.map(({bytes,label})=>target(bytes/1024,label)).join('')}<details class="preset-details"><summary>More sizes ${icon('down')}</summary><div class="preset-details-body">${[[20,'20 KB'],[50,'50 KB'],[150,'150 KB'],[200,'200 KB'],[300,'300 KB'],[5120,'5 MB']].map(([k,l])=>target(k,l)).join('')}</div></details></div><div class="preset-custom"><input id="customTarget" type="number" min="0.001" max="50000" step="any" value="200" aria-label="Custom target size"><select id="customTargetUnit" aria-label="Target size unit"><option value="KB">KB</option><option value="MB">MB</option></select><button class="btn btn-outline" id="applyTarget">Use custom size</button></div><div class="help-text">JPG or WebP only. Dimensions may shrink if downscaling is allowed; exact targets are not guaranteed. Limit: 5–50,000 KB; 1 MB = 1,024 KB.</div></div></details>
 <details class="preset-section preset-category"><summary class="preset-section-head"><h3>Resolution & file size</h3><span>COMBINED</span>${icon('down')}</summary><div class="preset-category-body"><button class="preset-inline" data-preset="combined">Set dimensions and a size limit ${icon('arrow')}</button></div></details>
 <details class="preset-section preset-category"><summary class="preset-section-head"><h3>Print</h3><span>300 DPI CALCULATION</span>${icon('down')}</summary><div class="preset-category-body"><div class="preset-list">${print}</div><button class="preset-inline" data-preset="custom-print">Custom mm, cm or inch ${icon('arrow')}</button><div class="help-text">Pixels = mm × DPI ÷ 25.4, cm × DPI ÷ 2.54, or inches × DPI. Print presets write DPI metadata to JPG/PNG.</div></div></details>
 <details class="preset-section preset-category"><summary class="preset-section-head"><h3>Social media</h3><span>PRESETS</span>${icon('down')}</summary><div class="preset-category-body"><div class="preset-list">${presetGroups(SOCIAL_PRESETS)}</div></div></details>
 <details class="preset-section preset-category"><summary class="preset-section-head"><h3>Marketplaces</h3><span>PRESETS</span>${icon('down')}</summary><div class="preset-category-body"><div class="preset-list">${presetGroups(MARKET_PRESETS)}</div><div class="help-text">These are convenient sizes, not guaranteed current platform requirements.</div></div></details></div>`;
 openSmall('Select dimensions',html);
 const root=$('#smallModalBody');
 root.onclick=e=>{const heading=e.target.closest('summary.preset-section-head');if(heading&&root.contains(heading)){const category=heading.parentElement;if(!category.open)root.querySelectorAll('.preset-category[open]').forEach(other=>{if(other!==category)other.open=false});return}const btn=e.target.closest('[data-preset]');if(!btn)return;try{const type=btn.dataset.preset;if(type==='easy')applyResizeEasy(btn.dataset.label,Number(btn.dataset.value),Number(btn.dataset.quality));else if(type==='percent')applyResizePercent(Number(btn.dataset.value));else if(type==='width')applyResizeWidth(Number(btn.dataset.value));else if(type==='exact')applyResizeExact(Number(btn.dataset.w),Number(btn.dataset.h),btn.dataset.label);else if(type==='print')applyResizePrint(Number(btn.dataset.w),Number(btn.dataset.h),btn.dataset.unit,btn.dataset.label);else if(type==='target')applyResizeTarget(Number(btn.dataset.value));else if(type==='custom-dimensions'){closeSmall();$('#resizeW').focus()}else if(type==='combined'){applyResizeTarget($('#limitTarget').checked?num('resizeTargetKB',200):200);$('#resizeW').focus()}else if(type==='custom-print'){const old=s.resizeUnit,dpi=Math.max(1,num('resizeDpi',300));const w=toPixels(num('resizeW',1),old,dpi),h=toPixels(num('resizeH',1),old,dpi);$('#resizeUnit').value='cm';s.resizeUnit='cm';s.resizePercent=null;$('#resizeW').value=roundSize(fromPixels(w,'cm',dpi),'cm');$('#resizeH').value=roundSize(fromPixels(h,'cm',dpi),'cm');enablePrintDpi();setResizeLabel('Custom print dimensions');closeSmall();$('#resizeW').focus()}}catch(err){toast(err.message||'Choose a valid preset.',true)}};
 $('#customPercent').addEventListener('input',e=>{const p=Number(e.target.value);$('#customPercentDimensions').textContent=Number.isFinite(p)&&p>=1&&p<=400?`${p}% → ${Math.max(1,Math.round(iw*p/100))} × ${Math.max(1,Math.round(ih*p/100))} px`:'Enter a percentage between 1 and 400.'});
 $('#applyPercent').addEventListener('click',()=>{try{applyResizePercent(Number($('#customPercent').value))}catch(err){toast(err.message,true)}});
 $('#applyTarget').addEventListener('click',()=>{try{const amount=Number($('#customTarget').value),unit=$('#customTargetUnit').value;applyResizeTarget(amount*(unit==='MB'?1024:1))}catch(err){toast(err.message,true)}});
 estimateEasySizes(s).catch(e=>console.warn('Size estimate unavailable',e));
}
function setResizeLabel(label){const el=$('#resizePresetLabel');if(el)el.textContent=label}
