 const small=new fabric.Textbox('YOUR CREATIVE SPACE',{left:116,top:135,width:245,fontFamily:'Arial',fontSize:15,fontWeight:'bold',charSpacing:80,fill:'#7965cc',name:'Label'});
 const title=new fabric.Textbox('MAKE IT\nBEAUTIFUL.',{left:93,top:210,width:500,fontFamily:'Arial',fontSize:78,fontWeight:'bold',lineHeight:1.05,fill:'#2b2849',name:'Headline'});
 const sub=new fabric.Textbox('A little idea can become something amazing.',{left:99,top:461,width:390,fontFamily:'Arial',fontSize:25,lineHeight:1.35,fill:'#79738f',name:'Subheading'});
