function editorSnapshot(){const c=ed.canvas;return JSON.stringify({width:c.getWidth(),height:c.getHeight(),canvas:c.toJSON(['name'])})}
function pushEditorHistory(){if(!ed.ready||ed.suppress)return;const snap=editorSnapshot();if(ed.history[ed.pointer]===snap)return;ed.history=ed.history.slice(0,ed.pointer+1);ed.history.push(snap);if(ed.history.length>40)ed.history.shift();ed.pointer=ed.history.length-1}
function restoreEditorSnapshot(snapshot,resetHistory=false){const data=typeof snapshot==='string'?JSON.parse(snapshot):snapshot;return new Promise((resolve,reject)=>{try{const c=ed.canvas;ed.suppress=true;c.setDimensions({width:data.width,height:data.height});c.loadFromJSON(data.canvas,()=>{c.discardActiveObject();c.renderAll();ed.suppress=false;if(resetHistory){ed.history=[];ed.pointer=-1;pushEditorHistory()}updateEditorUI();ed.zoom='fit';fitEditor();resolve()})}catch(e){ed.suppress=false;reject(e)}})}
async function editorHistory(delta){clearTimeout(ed.historyTimer);const next=ed.pointer+delta;if(next<0||next>=ed.history.length){toast(delta<0?'Nothing to undo.':'Nothing to redo.');return}ed.pointer=next;await restoreEditorSnapshot(ed.history[next])}
function fitEditor(){if(!ed.ready||$('#editorView').hidden)return;const stage=$('#canvasStage'),c=ed.canvas;const availW=Math.max(100,stage.clientWidth-52),availH=Math.max(100,stage.clientHeight-52);ed.fitScale=Math.min(availW/c.getWidth(),availH/c.getHeight(),1.4);const factor=ed.zoom==='fit'?ed.fitScale:ed.zoom;c.setDimensions({width:Math.round(c.getWidth()*factor)+'px',height:Math.round(c.getHeight()*factor)+'px'},{cssOnly:true});c.calcOffset();$('#zoomLabel').textContent=ed.zoom==='fit'?'Fit':`${Math.round(factor*100)}%`;$('#canvasSizeLabel').textContent=`${c.getWidth()} × ${c.getHeight()} px`}
function editorObjectName(obj){return obj.name||(obj.type==='textbox'||obj.type==='i-text'?'Text':obj.type==='image'?'Image':obj.type==='rect'?'Rectangle':obj.type==='circle'?'Circle':obj.type==='path'?'Drawing':'Shape')}
function updateEditorUI(){if(!ed.ready)return;const c=ed.canvas,o=c.getActiveObject(),objects=c.getObjects();$('#layerCount').textContent=objects.length;$('#layerList').innerHTML=[...objects].reverse().map((item,rev)=>{const i=objects.length-1-rev;return `<button class="layer-row ${item===o?'active':''}" data-layer="${i}">${icon(item.type==='image'?'image':item.type==='textbox'||item.type==='i-text'?'text':'layers')}<span>${esc(editorObjectName(item))}</span></button>`}).join('')||'<div class="prop-empty">Your layers will appear here.</div>';$('#layerList').querySelectorAll('[data-layer]').forEach(b=>b.addEventListener('click',()=>{const obj=c.getObjects()[Number(b.dataset.layer)];if(obj){c.setActiveObject(obj);c.requestRenderAll();updateEditorUI()}}));$('#selectionEmpty').hidden=!!o;$('#selectedProps').hidden=!o;$('#selectionName').textContent=o?editorObjectName(o).toUpperCase():'NONE';if(!o)return;const isText=['textbox','i-text','text'].includes(o.type),isImage=o.type==='image';$('#fontGroup').hidden=!isText;$('#edFilterGroup').hidden=!isImage;$('#edFillGroup').hidden=isImage;$('#edStrokeGroup').hidden=isImage;$('#edOpacity').value=Math.round((o.opacity??1)*100);$('#edOpacityVal').textContent=$('#edOpacity').value+'%';const gradient=!!(o.fill&&typeof o.fill==='object'&&o.fill.type==='linear');$('#edFillStyle').value=gradient?'gradient':'solid';$('#edGradientGroup').hidden=!gradient;function colorHex(c,fallback){try{return '#'+new fabric.Color(c).toHex()}catch{return fallback}}if(gradient){$('#edFill').value=colorHex(o.fill.colorStops?.[0]?.color,'#262444');$('#edFillEnd').value=colorHex(o.fill.colorStops?.[o.fill.colorStops.length-1]?.color,'#f2baad')}else if(typeof o.fill==='string')$('#edFill').value=colorHex(o.fill,'#262444');$('#edStrokeWidth').value=o.stroke?Math.round(o.strokeWidth||0):0;$('#edStroke').value=o.stroke?colorHex(o.stroke,'#ffffff'):'#ffffff';$('#edShadow').checked=!!o.shadow;if(isText){$('#edFont').value=o.fontFamily||'Arial';$('#edFontSize').value=Math.round(o.fontSize||64);$('#edTextAlign').value=o.textAlign||'left';$('#edBold').classList.toggle('active',String(o.fontWeight)==='bold'||Number(o.fontWeight)>=600)}if(isImage){const selected=(o.filters||[]).find(Boolean);const name=selected?.type?.toLowerCase()||'none';$('#edFilter').value=['grayscale','sepia','invert','vintage','blur'].includes(name)?name:'none'}}
function addEditorObject(obj){const c=ed.canvas;ed.suppress=true;c.add(obj);c.setActiveObject(obj);c.centerObject(obj);obj.setCoords();c.requestRenderAll();ed.suppress=false;updateEditorUI();pushEditorHistory()}
$('#edText').addEventListener('click',()=>{const o=new fabric.Textbox('Your text here',{width:440,fontSize:65,fontFamily:'Arial',fontWeight:'bold',fill:'#28263e',name:'Text'});addEditorObject(o);toast('Double-click the text to edit it.')});
