$('#edImage').addEventListener('click',()=>$('#edImageInput').click());$('#edImageInput').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader();reader.onerror=()=>toast('Could not read the image.',true);reader.onload=()=>fabric.Image.fromURL(reader.result,img=>{if(!img||!img.width){toast('This image format is not supported by the browser.',true);return}img.set({name:baseName(file.name)});img.scaleToWidth(Math.min(ed.canvas.width*.6,img.width));addEditorObject(img)},{});reader.readAsDataURL(file);e.target.value=''});
$('#edDraw').addEventListener('click',()=>{const c=ed.canvas;c.isDrawingMode=!c.isDrawingMode;$('#edDraw').classList.toggle('active',c.isDrawingMode);if(c.isDrawingMode){c.discardActiveObject();c.freeDrawingBrush=new fabric.PencilBrush(c);c.freeDrawingBrush.width=7;c.freeDrawingBrush.color='#6e5ce6';toast('Draw directly on the canvas. Tap Draw again to stop.')}else toast('Drawing mode off.');c.requestRenderAll();updateEditorUI()});
$('#edUndo').addEventListener('click',()=>editorHistory(-1));$('#edRedo').addEventListener('click',()=>editorHistory(1));
$('#zoomFit').addEventListener('click',()=>{ed.zoom='fit';fitEditor()});$('#zoomIn').addEventListener('click',()=>{ed.zoom=Math.min(2,(ed.zoom==='fit'?ed.fitScale:ed.zoom)*1.2);fitEditor()});$('#zoomOut').addEventListener('click',()=>{ed.zoom=Math.max(.1,(ed.zoom==='fit'?ed.fitScale:ed.zoom)/1.2);fitEditor()});
$('#edPreset').addEventListener('change',e=>{const [w,h]=e.target.value.split('x').map(Number);ed.canvas.setDimensions({width:w,height:h});ed.canvas.requestRenderAll();ed.zoom='fit';fitEditor();pushEditorHistory()});
$('#edBg').addEventListener('input',e=>{ed.canvas.setBackgroundColor(e.target.value,ed.canvas.renderAll.bind(ed.canvas))});$('#edBg').addEventListener('change',pushEditorHistory);
function setSelected(key,value){const o=ed.canvas?.getActiveObject();if(!o)return;o.set(key,value);o.setCoords();ed.canvas.requestRenderAll()}
function applyEditorFill(){const o=ed.canvas?.getActiveObject();if(!o||o.type==='image')return;const gradient=$('#edFillStyle').value==='gradient';$('#edGradientGroup').hidden=!gradient;o.set('fill',gradient?new fabric.Gradient({type:'linear',gradientUnits:'percentage',coords:{x1:0,y1:0,x2:1,y2:1},colorStops:[{offset:0,color:$('#edFill').value},{offset:1,color:$('#edFillEnd').value}]}):$('#edFill').value);ed.canvas.requestRenderAll()}
for(const id of ['edFill','edFillEnd']){$('#'+id).addEventListener('input',applyEditorFill);$('#'+id).addEventListener('change',pushEditorHistory)}$('#edFillStyle').addEventListener('change',()=>{applyEditorFill();pushEditorHistory()});function applyEditorStroke(){const o=ed.canvas?.getActiveObject();if(!o||o.type==='image')return;const w=Math.max(0,Math.min(40,num('edStrokeWidth',0)));o.set({stroke:w?$('#edStroke').value:null,strokeWidth:w});ed.canvas.requestRenderAll()}for(const id of ['edStroke','edStrokeWidth']){$('#'+id).addEventListener('input',applyEditorStroke);$('#'+id).addEventListener('change',pushEditorHistory)}$('#edShadow').addEventListener('change',e=>{setSelected('shadow',e.target.checked?new fabric.Shadow({color:'rgba(29,26,61,.28)',blur:18,offsetX:6,offsetY:7}):null);pushEditorHistory()});$('#edTextAlign').addEventListener('change',e=>{setSelected('textAlign',e.target.value);pushEditorHistory()});$('#edCenter').addEventListener('click',()=>{const o=ed.canvas?.getActiveObject();if(o){ed.canvas.centerObject(o);o.setCoords();ed.canvas.requestRenderAll();pushEditorHistory()}});$('#edOpacity').addEventListener('input',e=>{setSelected('opacity',Number(e.target.value)/100);$('#edOpacityVal').textContent=e.target.value+'%'});$('#edOpacity').addEventListener('change',pushEditorHistory);
$('#edFont').addEventListener('change',e=>{setSelected('fontFamily',e.target.value);pushEditorHistory()});$('#edFontSize').addEventListener('input',e=>{const n=Math.max(8,Math.min(400,Number(e.target.value)||8));setSelected('fontSize',n)});$('#edFontSize').addEventListener('change',pushEditorHistory);$('#edBold').addEventListener('click',()=>{const o=ed.canvas.getActiveObject();if(o){o.set('fontWeight',o.fontWeight==='bold'?'normal':'bold');ed.canvas.requestRenderAll();updateEditorUI();pushEditorHistory()}});
$('#edFilter').addEventListener('change',e=>{const o=ed.canvas.getActiveObject();if(!o||o.type!=='image')return;const f=e.target.value,F=fabric.Image.filters;const map={grayscale:()=>new F.Grayscale(),sepia:()=>new F.Sepia(),invert:()=>new F.Invert(),vintage:()=>new F.Vintage(),blur:()=>new F.Blur({blur:.2})};o.filters=f==='none'?[]:[map[f]()];o.applyFilters();ed.canvas.requestRenderAll();pushEditorHistory()});
$('#edDuplicate').addEventListener('click',()=>{const o=ed.canvas.getActiveObject();if(!o)return;o.clone(copy=>{copy.set({left:o.left+25,top:o.top+25,name:editorObjectName(o)+' copy'});ed.canvas.add(copy);ed.canvas.setActiveObject(copy);copy.setCoords();ed.canvas.requestRenderAll();updateEditorUI()})});
$('#edForward').addEventListener('click',()=>{const o=ed.canvas.getActiveObject();if(o){ed.canvas.bringForward(o);ed.canvas.requestRenderAll();updateEditorUI();pushEditorHistory()}});$('#edBackward').addEventListener('click',()=>{const o=ed.canvas.getActiveObject();if(o){ed.canvas.sendBackwards(o);ed.canvas.requestRenderAll();updateEditorUI();pushEditorHistory()}});$('#edDelete').addEventListener('click',()=>{const c=ed.canvas,o=c.getActiveObject();if(o){c.remove(o);c.discardActiveObject();c.requestRenderAll();updateEditorUI()}});
document.addEventListener('keydown',e=>{if(stateApp.view!=='editor'||!ed.ready||!$('#toolModal').hidden||!$('#smallModal').hidden)return;const t=e.target;if(/input|textarea|select/i.test(t.tagName)||t.isContentEditable||ed.canvas.getActiveObject()?.isEditing)return;if(e.key==='Delete'||e.key==='Backspace'){const obj=ed.canvas.getActiveObject();if(obj){e.preventDefault();$('#edDelete').click()}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();editorHistory(e.shiftKey?1:-1)}});
$('#editorNew').addEventListener('click',()=>{openSmall('Start a new canvas?',`<p>This clears the current design. Save a project first if you want to edit it again later.</p><div class="input-pair" style="margin-top:18px"><button class="btn btn-outline" id="cancelNew">Cancel</button><button class="btn btn-primary" id="confirmNew">Start fresh</button></div>`);$('#cancelNew').onclick=closeSmall;$('#confirmNew').onclick=()=>{const c=ed.canvas;ed.suppress=true;c.clear();c.setBackgroundColor('#ffffff',c.renderAll.bind(c));c.setDimensions({width:1200,height:800});$('#edBg').value='#ffffff';$('#edPreset').value='1200x800';ed.suppress=false;pushEditorHistory();ed.zoom='fit';fitEditor();updateEditorUI();closeSmall()}});
$('#editorSave').addEventListener('click',()=>{const snap=JSON.parse(editorSnapshot());const project={type:'pixora-project',version:1,...snap};download(new Blob([JSON.stringify(project)],{type:'application/json'}),'pixora-project.json')});
$('#editorOpen').addEventListener('click',()=>$('#edProjectInput').click());$('#edProjectInput').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>35000000)throw new Error('Project file is too large.');const project=JSON.parse(await file.text());if(project.type!=='pixora-project'||!project.canvas||!Array.isArray(project.canvas.objects))throw new Error('Please select a Pixora project JSON file.');checkDimensions(project.width,project.height);const scan=(o)=>{if(!o||typeof o!=='object')return;if(o.src&&typeof o.src==='string'&&!/^data:image\//i.test(o.src))throw new Error('Project images must be embedded; external image URLs are not allowed.');Object.values(o).forEach(scan)};scan(project.canvas);await restoreEditorSnapshot(project,true);$('#edBg').value=/^#[0-9a-f]{6}$/i.test(ed.canvas.backgroundColor)?ed.canvas.backgroundColor:'#ffffff';toast('Project opened.')}catch(err){toast(err.message||'Could not open project.',true)}});
$('#editorExport').addEventListener('click',()=>{openSmall('Export your design',`<p>Choose a format. Your design is exported at its full canvas size.</p><div class="control-group"><label for="exportFormat">File format</label>${select('exportFormat',[['png','PNG · best for transparency'],['jpg','JPG · smaller file'],['pdf','PDF · one page']])}</div><div class="input-pair" style="margin-top:18px"><button class="btn btn-outline" id="cancelExport">Cancel</button><button class="btn btn-primary" id="confirmExport">${icon('download')} Export design</button></div>`);$('#cancelExport').onclick=closeSmall;$('#confirmExport').onclick=async()=>{const c=ed.canvas,format=val('exportFormat','png'),btn=$('#confirmExport');btn.disabled=true;try{c.discardActiveObject();c.requestRenderAll();const data=c.toDataURL({format:format==='jpg'?'jpeg':'png',quality:.92,multiplier:1,enableRetinaScaling:false});const bytes=dataURLBytes(data);let blob,name;if(format==='pdf'){const doc=await PDFLib.PDFDocument.create(),image=await doc.embedPng(bytes),scale=Math.min(1,14000/Math.max(c.width,c.height)),page=doc.addPage([c.width*scale,c.height*scale]);page.drawImage(image,{x:0,y:0,width:c.width*scale,height:c.height*scale});blob=pdfBlob(await doc.save());name='pixora-design.pdf'}else{blob=new Blob([bytes],{type:format==='jpg'?'image/jpeg':'image/png'});name=`pixora-design.${format}`}closeSmall();download(blob,name);updateEditorUI()}catch(err){btn.disabled=false;toast(err.message||'Could not export the design.',true)}}});
